#include <iostream>
#include <string>

class Student {
public:
    // Mutator (set) - allows controlled modification
    void setId(int idNumber) {
        studentId = idNumber;
    }

    // Accessor (get) - const ensures object state is not modified
    int getId() const {
        return studentId;
    }

private:
    int studentId{0}; // Private data member encapsulated
};

int main() {
    Student s1;
    Student s2;

    s1.setId(101);
    s2.setId(202);

    std::cout << "Student 1 ID: " << s1.getId() << "\n";
    std::cout << "Student 2 ID: " << s2.getId() << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <string_view>

class GradeBook {
public:
    // C++17 best practice: accept string_view or pass by value/move
    void setCourseName(std::string_view name) {
        courseName = name;
    }

    // Accessor marked const as it does not modify object state
    std::string getCourseName() const {
        return courseName;
    }

    // displayMessage delegates retrieval to getCourseName()
    void displayMessage() const {
        std::cout << "Welcome to the grade book for\n" 
                  << getCourseName() << "!\n";
    }

private:
    std::string courseName; // Default-initialized to empty string ""
};

int main() {
    GradeBook myGradeBook;

    // Initial state check: default string is empty
    std::cout << "Initial course name is: " << myGradeBook.getCourseName() << "\n";

    std::string nameOfCourse;
    std::cout << "\nPlease enter the course name:\n";
    if (std::getline(std::cin, nameOfCourse)) {
        myGradeBook.setCourseName(nameOfCourse);
    }

    std::cout << "\n";
    myGradeBook.displayMessage();

    return 0;
}
